<template>
 <article class="reset-plan-card" :class="[plan.phase,{success}]" :aria-label="success?copy.successKicker:copy.kicker">
  <div class="reset-plan-kicker"><span class="reset-plan-dot"></span>{{ success?copy.successKicker:copy.kicker }}<span class="reset-plan-tag">{{ copy[plan.phase] }}</span></div>
