  <div v-if="plan.phase==='scheduled'" class="reset-plan-countdown" role="timer">{{ countdown }}</div>
  <p v-else class="reset-plan-state">{{ plan.phase==='awaiting'?copy.waiting:plan.phase==='observed'?copy.observedHelp:plan.phase==='completed'?(plan.observation?copy.confirmedHelp:copy.done):copy.cancelledHelp }}</p>
  <div class="reset-plan-time"><span>{{ plan.before?(language==='zh'?'截止时间':'Before'):plan.phase==='scheduled'&&plan.approximate?(language==='zh'?'最晚约':'By about'):copy.target }}</span><strong>{{ time(plan.scheduledAt) }}{{ plan.before&&language==='zh'?' 之前':'' }}</strong><span>{{ zoneName }}</span></div>
  <p v-if="sourcePst" class="reset-plan-evidence">{{ language==='zh'?'按原文 PST（UTC−8）换算；若来源实际指 PDT，则早 1 小时。':'Converted from the stated PST (UTC−8); if the source meant PDT, it is 1 hour earlier.' }}</p>
