  <p v-else-if="success && plan.confirmation" class="reset-plan-evidence"><strong>{{ copy.confirmedAt }}</strong> {{ time(plan.confirmation.postedAt) }} · {{ zoneName }}</p>
  <p v-if="success" class="reset-plan-duration">{{ copy.successDuration }}</p>
  <p class="reset-plan-explainer">{{ success?copy.observationScope:copy.explainer }}</p>
  <p v-if="stale" class="reset-plan-stale">{{ copy.stale }}</p>
  <div class="reset-plan-footer"><span>Tibo · @thsottiaux</span><WebButton class="base-button" @click="$emit('detail',plan.record)">{{ copy.source }} ↗</WebButton><WebButton v-if="plan.confirmation" class="base-button" @click="$emit('detail',plan.confirmation)">{{ copy.confirmation }} ↗</WebButton><a v-if="plan.observation" :href="plan.observation.confirmationUrl || 'https://codex-reset.com'" target="_blank" rel="noopener noreferrer">{{ copy.evidence }} ↗</a></div>
 </article>
</template>
