defineEmits(['detail']);
const countdown=computed(()=>formatPlanCountdown(props.plan.remainingMs));
const success=computed(()=>['observed','completed'].includes(props.plan.phase));
const sourcePst=computed(()=>/\bPST\b/i.test(props.plan.record.original||''));
const copy=computed(()=>props.language==='zh'?{
 successKicker:'重置好消息',celebrate:'快去享受 GPT 吧！',successDuration:'完成提示保留 1 小时，之后恢复日常概览。',kicker:'来源已公布重置计划',observed:'来源实测已重置',observedHelp:'来源已实测到额度重置，可以回到 ChatGPT / Codex 看看了。',observedAt:'来源观测时间',confirmedAt:'确认公告时间',evidence:'查看确认来源',confirmedHelp:'Tibo 已确认重置完成，祝你用得尽兴。',observationScope:'完成依据见来源；你的可用额度请以账号实际显示为准。',scheduled:'计划中',awaiting:'等待完成确认',completed:'来源已发布完成公告',cancelled:'计划已取消',countdown:'距离计划时间',waiting:'计划时间已到，仍需等待来源确认完成。',done:'Tibo 已确认重置完成，祝你用得尽兴。',cancelledHelp:'来源已取消或推迟此计划，等待新的明确安排。',target:'原定计划时间',explainer:'这是一项已公布的计划，不是概率预测，也不代表你的账号额度已恢复。',stale:'来源更新暂不可用，计划可能已变化，请核对原文。',source:'查看计划原文',confirmation:'查看后续公告'
}:{successKicker:'Reset update',celebrate:'Time to enjoy GPT!',successDuration:'This update stays for 1 hour, then the regular overview returns.',kicker:'Reset plan announced by source',observed:'Reset observed by source',observedHelp:'The source has observed a usage reset. Head back to ChatGPT / Codex.',observedAt:'Source observation time',confirmedAt:'Confirmation published',evidence:'View confirmation source',confirmedHelp:'Tibo has confirmed the reset. Enjoy your next session.',observationScope:'See the source for reset evidence. Check your own account for available usage.',scheduled:'Scheduled',awaiting:'Awaiting confirmation',completed:'Source reported completion',cancelled:'Plan cancelled',countdown:'Until the planned time',waiting:'The target time has passed. Completion still needs confirmation.',done:'Tibo has confirmed the reset. Enjoy your next session.',cancelledHelp:'The source cancelled or postponed this plan. Await a new explicit schedule.',target:'Originally planned for',explainer:'An announced plan, not a probability estimate or confirmation of your account allowance.',stale:'Source updates are unavailable. The plan may have changed; check the original.',source:'Read original plan',confirmation:'Read follow-up'});
